function logOptionLabel(item){const name=String(item.name||'').toLowerCase();let kind=item.category==='oauth'?'登录记录':'系统记录';if(name.includes('stderr'))kind='错误记录';else if(name.includes('stdout'))kind='运行记录';if(name.includes('archive'))kind='历史记录';return `${kind} · ${formatTime(item.modified_at)}`}
