function friendlyLogSource(event){const source=eventSource(event).toLowerCase();if(source.includes('sms')||source.includes('hero'))return '接码';if(source.includes('outlook')||source.includes('mail')||source.includes('generic'))return '邮箱';if(source.includes('codex')||source.includes('oauth'))return '登录';if(source.includes('sentinel'))return '验证';return '系统'}
function friendlyLogState(event){const level=String(event&&event.severity_text||'UNKNOWN').toLowerCase();if(event&&event.problem||level==='fatal'||level==='error')return {label:'失败',icon:'×',className:'error'};if(level==='warn'||level==='warning')return {label:'警告',icon:'!',className:'reminder'};if(level==='info'||level==='notice')return {label:'正常',icon:'●',className:'normal'};if(level==='debug'||level==='trace')return {label:'调试',icon:'·',className:'debug'};return {label:'其他',icon:'·',className:'other'}}
