function smsStatNumber(value){const number=Number(value);return Number.isFinite(number)?number:0}
function formatSmsCount(value){return Math.max(0,smsStatNumber(value)).toLocaleString('zh-CN',{maximumFractionDigits:0})}
function normalizedSmsRate(value){if(value===null||value===undefined||value==='')return null;const number=Number(String(value).replace('%',''));return Number.isFinite(number)?number:null}
function formatSmsRate(value){const rate=normalizedSmsRate(value);return rate===null?'—':`${rate.toLocaleString('zh-CN',{minimumFractionDigits:rate%1?1:0,maximumFractionDigits:1})}%`}
function smsRateTone(value){const rate=normalizedSmsRate(value);if(rate===null)return '';if(rate>=70)return 'good';if(rate>=35)return 'warn';return 'bad'}
function formatSmsPrice(value){if(value===null||value===undefined||value==='')return '—';const number=Number(value);return Number.isFinite(number)?number.toLocaleString('zh-CN',{minimumFractionDigits:0,maximumFractionDigits:4}):String(value)}
function displaySmsPhone(value){const text=String(value||'').trim();return text||'—'}
function smsCountryMarkup(row){const name=row.name||`国家 ${row.country_id||'未知'}`,secondary=row.name_en&&row.name_en!==name?row.name_en:`国家 ID ${row.country_id||'—'}`;return `<div class="sms-stats-country"><span class="sms-stats-country-flag">${esc(row.flag||'🌐')}</span><span class="sms-stats-country-copy"><strong>${esc(name)}</strong><small>${esc(secondary)}</small></span></div>`}
function smsMetricMarkup(label,value,note,tone=''){return `<div class="sms-stat-metric ${esc(tone)}"><span class="sms-stat-metric-label">${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`}
function smsRecordTone(record){const status=String(record.status||'').toLowerCase();if(record.verified||['verified','success','completed','complete'].includes(status))return 'good';if(['fraud_guard','number_in_use','rate_limited','send_rejected','sms_timeout','code_rejected','replaced'].includes(status)||/(fail|error|cancel|reject|timeout)/.test(status))return 'bad';if(record.code_received||record.sms_sent||/(pending|waiting|sent|received|acquired)/.test(status))return 'warn';return ''}
function renderSmsStats(data){
  smsStatsData=data&&typeof data==='object'?data:{};
  const summary=smsStatsData.summary&&typeof smsStatsData.summary==='object'?smsStatsData.summary:{};
  const countries=Array.isArray(smsStatsData.countries)?smsStatsData.countries:[];
  const records=Array.isArray(smsStatsData.records)?smsStatsData.records:[];
  $('#smsStatsUpdated').textContent=smsStatsData.generated_at?`${formatTime(smsStatsData.generated_at)} 更新`:'刚刚更新';
  $('#smsStatsOverview').innerHTML=[
    smsMetricMarkup('已拿号码',formatSmsCount(summary.numbers_acquired),`已发短信 ${formatSmsCount(summary.sms_sent)} 次`),
    smsMetricMarkup('收到验证码',formatSmsCount(summary.codes_received),`待处理 ${formatSmsCount(summary.pending)} 个`,'warn'),
    smsMetricMarkup('验证成功',formatSmsCount(summary.verified),`失败 ${formatSmsCount(summary.failed)} 个`,'good'),
    smsMetricMarkup('总体成功率',formatSmsRate(summary.success_rate),`${formatSmsCount(summary.verified)} 个号码验证成功`,smsRateTone(summary.success_rate)),
    smsMetricMarkup('平均报价',formatSmsPrice(summary.quoted_average),`${formatSmsCount(summary.priced_numbers)} 个号码有报价`)
  ].join('');
  const notes=[smsStatsData.success_rate_note,smsStatsData.price_note].filter((value,index,items)=>value&&items.indexOf(value)===index);
  $('#smsStatsNotes').innerHTML=notes.length?notes.map(note=>`<span class="sms-stats-note">${esc(note)}</span>`).join(''):'<span class="sms-stats-note">统计基于本机已归档的接码记录</span>';
  $('#smsCountryCount').textContent=`${countries.length} 个国家`;
  if(!countries.length){
    $('#smsCountryStats').innerHTML='<div class="sms-stats-empty">暂无按国家汇总的数据</div>';
  }else{
    $('#smsCountryStats').innerHTML=`<div class="table-scroll"><table class="sms-stats-table sms-country-table"><caption class="sr-only">各国家接码成功率与平均报价</caption><thead><tr><th scope="col">国家</th><th scope="col">拿号</th><th scope="col">发短信</th><th scope="col">收码</th><th scope="col">已验证</th><th scope="col">失败 / 待处理</th><th scope="col">成功率</th><th scope="col">平均报价</th></tr></thead><tbody>${countries.map(row=>`<tr><td>${smsCountryMarkup(row)}</td><td>${esc(formatSmsCount(row.numbers_acquired))}</td><td>${esc(formatSmsCount(row.sms_sent))}</td><td>${esc(formatSmsCount(row.codes_received))}</td><td>${esc(formatSmsCount(row.verified))}</td><td>${esc(formatSmsCount(row.failed))} / ${esc(formatSmsCount(row.pending))}</td><td><span class="sms-stat-rate ${esc(smsRateTone(row.success_rate))}">${esc(formatSmsRate(row.success_rate))}</span></td><td class="mono">${esc(formatSmsPrice(row.quoted_average))}</td></tr>`).join('')}</tbody></table></div>`;
  }
  const recordsTotal=Math.max(records.length,smsStatNumber(smsStatsData.records_total));
  $('#smsRecordCount').textContent=smsStatsData.records_truncated?`最新 ${records.length} / 共 ${formatSmsCount(recordsTotal)}`:`${records.length} 条记录`;
  if(!records.length){
    $('#smsNumberRecords').innerHTML='<div class="sms-stats-empty">暂无号码明细</div>';
    return;
  }
  $('#smsNumberRecords').innerHTML=`<div class="table-scroll"><table class="sms-stats-table"><caption class="sr-only">接码号码明细</caption><thead><tr><th scope="col">拿号时间</th><th scope="col">国家</th><th scope="col">完整号码</th><th scope="col">报价</th><th scope="col">状态</th><th scope="col">尝试</th><th scope="col">说明</th></tr></thead><tbody>${records.map(record=>{
    const flags=[record.sms_sent?'已发短信':'',record.code_received?'已收码':'',record.verified?'已验证':''].filter(Boolean).join(' · ');
    const detail=[record.detail,flags].filter(Boolean).join(' · ');
    const attempt=record.attempt===null||record.attempt===undefined?'—':formatSmsCount(record.attempt);
    const maximum=record.max_attempts===null||record.max_attempts===undefined?'—':formatSmsCount(record.max_attempts);
    return `<tr><td class="muted">${esc(formatTime(record.acquired_at))}${record.completed_at?`<div class="section-note">完成 ${esc(formatTime(record.completed_at))}</div>`:''}</td><td>${smsCountryMarkup(record)}</td><td><span class="sms-phone-mask">${esc(displaySmsPhone(record.phone_number))}</span></td><td class="mono">${esc(formatSmsPrice(record.price))}</td><td><span class="sms-record-status ${esc(smsRecordTone(record))}">${esc(record.status_label||record.status||'未知')}</span></td><td class="mono">${esc(attempt)} / ${esc(maximum)}</td><td><div class="sms-record-detail">${esc(detail||'—')}</div></td></tr>`;
  }).join('')}</tbody></table></div>`;
}
function renderSmsStatsError(error){if(!smsStatsData){$('#smsStatsOverview').innerHTML=`<div class="sms-stats-empty sms-stats-error" style="grid-column:1/-1">统计加载失败：${esc(error.message)}</div>`;$('#smsStatsNotes').textContent='';$('#smsCountryStats').innerHTML='<div class="sms-stats-empty">暂时无法读取国家统计</div>';$('#smsNumberRecords').innerHTML='<div class="sms-stats-empty">暂时无法读取号码明细</div>';$('#smsCountryCount').textContent='—';$('#smsRecordCount').textContent='—'}$('#smsStatsUpdated').textContent='自动更新失败，已保留上次数据'}
async function loadSmsStats({silent=false}={}){if(smsStatsLoading)return smsStatsLoading;const content=$('#smsStatsContent');content.setAttribute('aria-busy','true');smsStatsLoading=(async()=>{try{const data=await api('/api/artifacts/sms-stats');renderSmsStats(data)}catch(error){renderSmsStatsError(error);if(!silent)toast('接码统计读取失败：'+error.message)}finally{content.setAttribute('aria-busy','false');smsStatsLoading=null}})();return smsStatsLoading}
