  async function loadHeroCatalog(){if(heroCatalogLoaded){fillHeroCountries(heroCountries);return}if(heroCatalogLoading)return heroCatalogLoading;$('#heroCatalogState').textContent='正在加载中文国家目录……';heroCatalogLoading=(async()=>{try{const j=await api('/api/hero-sms/catalog');heroCountries=Array.isArray(j.countries)?j.countries:[];heroCatalogLoaded=true;fillHeroCountries(heroCountries);$('#heroCatalogState').textContent=j.source==='live'?`已加载 ${heroCountries.length} 个国家名称。`:`官方目录暂时不可用，当前显示 ${heroCountries.length} 个常用国家。`}catch(e){$('#heroCatalogState').textContent='国家目录加载失败：'+e.message;countryPickers.forEach(p=>p.render())}finally{heroCatalogLoading=null}})();return heroCatalogLoading}
